UPDATE user_points
SET points = points - #{cost}
WHERE user_id = #{userId}
  AND points >= #{cost}

UPDATE user_points
SET points       = points + #{delta},
    total_points = total_points + #{delta}
WHERE user_id = #{userId}

UPDATE user_points
SET points = points + #{delta}
WHERE user_id = #{userId}
  AND points + #{delta} >= 0
